/* Written by tools/build_film.mjs from narration/film.json: do not edit. Times are seconds. */
export const FILM = {"audio":"assets/audio/film.mp3","voice":"elevenlabs-atma","length":498.98,"steps":[{"id":"aube","from":0,"arrive":0,"voice":1.2,"leave":13.12,"lines":[{"at":1.28,"end":4.27,"text":"Portivechju. Lettre à ceux qui reviennent.","quiet":true},{"at":5.41,"end":11.92,"text":"À vous qui portez ce pays dans un nom, dans une maison, ou simplement dans une façon de dire « là-bas ».","quiet":true}],"cues":{},"pins":{}},{"id":"maquette","from":13.12,"arrive":20.12,"voice":15.52,"leave":29.9,"lines":[{"at":15.6,"end":23.04,"text":"Pour comprendre comment cette ville est née, il faut d’abord l’effacer — ôter les maisons, les quais, et revenir à la pierre nue."},{"at":23.28,"end":25.69,"text":"Un vieux proverbe corse le dit mieux que nous."},{"at":25.83,"end":28.8,"text":"Chì và è volta, bon viaghju face.","sub":"Celui qui part et revient a fait un bon voyage.","kind":"proverb"}],"cues":{},"pins":{}},{"id":"rocher","from":29.9,"arrive":37.9,"voice":32.5,"leave":50.56,"lines":[{"at":32.66,"end":39.11,"text":"Un golfe profond, refermé sur lui-même, et au fond de l’eau, un éperon de porphyre rose."},{"at":39.7,"end":42.38,"text":"Derrière lui, la montagne se lève aussitôt."},{"at":42.84,"end":49.86,"text":"Portivechju, le port vieux. Six siècles avant notre ère, dit-on, des Grecs de Syracuse y mouillaient déjà."}],"cues":{},"pins":{}},{"id":"port-vieux","from":50.56,"arrive":56.56,"voice":51.96,"leave":70.16,"lines":[{"at":52.04,"end":59.17,"text":"Un port, mais pas de ville. La plaine est fertile, pourtant personne n’ose y dormir : les marais donnent la fièvre."},{"at":59.47,"end":64.34,"text":"L’hiver seulement, les bergers descendent avec leurs troupeaux. Dès les chaleurs, ils remontent."},{"at":64.79,"end":69.16,"text":"Ce va-et-vient entre la montagne et la mer, c’est le premier battement de ce pays."}],"cues":{},"pins":{}},{"id":"citadelle","from":70.16,"arrive":93.36,"voice":72.96,"leave":94.36,"lines":[{"at":73.06,"end":80.4,"text":"Les corsaires se cachent dans ce golfe. En 1539, Gênes veut leur fermer ce refuge et choisit la hauteur du rocher."},{"at":80.6,"end":86.97,"text":"De 1541 à 1544, les remparts montent autour de la butte, défendus par cinq bastions."},{"at":88,"end":90.8,"text":"Derrière eux, Gênes installe ses premiers colons."}],"cues":{},"pins":{"bastion":80.6}},{"id":"ventimiglia","from":94.36,"arrive":100.36,"voice":95.76,"leave":112.12,"lines":[{"at":95.84,"end":102.28,"text":"Mais la ville ne tient pas. Sampiero Corso la prend en 1564 ; l’année suivante, tout est rasé."},{"at":102.64,"end":106.01,"text":"Des familles de Vintimille la relèvent, puis repartent à leur tour."},{"at":106.24,"end":111.12,"text":"Les pierres résistent, trois fois reconstruites. Il ne manquait que des gens pour rester."}],"cues":{},"pins":{}},{"id":"ceux-d-en-haut","from":112.12,"arrive":120.12,"voice":114.72,"leave":129.94,"lines":[{"at":114.8,"end":121.61,"text":"Alors Gênes lève les yeux vers la montagne. Des familles d’en haut, de Quenza surtout, descendent habiter la citadelle."},{"at":121.8,"end":129.04,"text":"Les deux noms de cette lettre viennent aussi de là-haut — les Rocca Serra, de Serra-di-Scopamène ; les Abbatucci, de Zicavo."}],"cues":{},"pins":{}},{"id":"estive","from":129.94,"arrive":134.94,"voice":131.34,"leave":150.82,"lines":[{"at":131.41,"end":133.83,"text":"Ils tiennent la ville, mais jamais toute l’année."},{"at":134.18,"end":141.19,"text":"Chaque été, quand revient la fièvre, on ferme les volets et l’on remonte vers Quenza, Zonza, Levie, l’Ospédale."},{"at":141.41,"end":145.91,"text":"À l’automne, on redescend. Une ville qui survit parce qu’elle sait se vider."},{"at":146.12,"end":149.42,"text":"Ici, partir n’a jamais été le contraire d’appartenir."}],"cues":{},"pins":{}},{"id":"paoli","from":150.82,"arrive":158.82,"voice":153.42,"leave":174.58,"lines":[{"at":153.53,"end":161.94,"text":"1769. L’année même où l’on commence la première carte précise de ce rivage, le golfe voit le plus célèbre de ses départs."},{"at":162.37,"end":169.07,"text":"Le 13 juin, vaincu à Ponte Novu, Pasquale Paoli embarque ici sur un navire anglais, direction l’exil."},{"at":169.52,"end":171.98,"text":"Quelque trois cents fidèles prennent la mer avec lui."}],"cues":{"sail":162.37},"pins":{}},{"id":"abbatucci","from":174.58,"arrive":180.58,"voice":175.98,"leave":204.26,"lines":[{"at":176.16,"end":180.82,"text":"L’homme qui a couvert sa retraite vient de Zicavo — Jacques Pierre Abbatucci."},{"at":181.36,"end":185.18,"text":"Paoli l’avait autrefois fait emprisonner, avant de lui confier tout le Sud."},{"at":185.68,"end":189.15,"text":"Dans la mémoire de la famille, c’est lui qui l’escorte jusqu’à ce port."},{"at":189.66,"end":195.89,"text":"Paoli reviendra vingt et un ans plus tard. Mais Jean-Charles, le fils du vieux général, ne rentrera jamais."},{"at":196.58,"end":202.86,"text":"Général à son tour, il tombe à vingt-six ans devant Huningue. Son nom est gravé sous l’Arc de triomphe."}],"cues":{},"pins":{"jp":176.16,"jc":189.66}},{"id":"sel","from":204.26,"arrive":211.26,"voice":206.86,"leave":219.4,"lines":[{"at":207.02,"end":213.11,"text":"Là où le Stabiacciu rejoint le golfe, l’eau dort dans les marais. Gênes y avait toujours interdit le sel."},{"at":213.53,"end":218.7,"text":"En 1795, les Rocca Serra reçoivent enfin le droit d’y aménager des salines."}],"cues":{},"pins":{}},{"id":"sauniers","from":219.4,"arrive":225.4,"voice":220.8,"leave":240.18,"lines":[{"at":220.88,"end":226.81,"text":"On y récoltera le sel deux siècles durant, jusqu’en l’an 2000 — les dernières salines de l’île."},{"at":227.45,"end":232.25,"text":"En 1803, le nom entre aussi à la mairie, pour y rester presque sans interruption."},{"at":232.71,"end":238.88,"text":"Le sel conserve ce qu’on lui confie. L’eau calme qui ouvre cette lettre, c’est celle de ces bassins."}],"cues":{},"pins":{"plan":220.88}},{"id":"liege","from":240.18,"arrive":247.18,"voice":242.78,"leave":258.12,"lines":[{"at":242.86,"end":251.9,"text":"Un siècle passe. Sur la Marine, dès 1876, une usine travaille le liège des collines — bouchons, flotteurs, isolants."},{"at":252.22,"end":257.42,"text":"On lève l’écorce au cœur de juillet, sous la chaleur lourde, quand il faudrait déjà être en montagne."}],"cues":{},"pins":{}},{"id":"ecorce","from":258.12,"arrive":263.12,"voice":259.52,"leave":277.2,"lines":[{"at":259.62,"end":268.48,"text":"Le chêne-liège se laisse dépouiller sans mourir. Nu, son tronc rougeoyant affronte le soleil ; dix à douze ans plus tard, l’écorce est revenue."},{"at":268.96,"end":276,"text":"L’usine ferme en 1975, vaincue par le plastique. Aujourd’hui, entre ses murs, on joue du théâtre."}],"cues":{},"pins":{}},{"id":"train","from":277.2,"arrive":287.2,"voice":281.2,"leave":295.36,"lines":[{"at":281.28,"end":286.07,"text":"En 1935, le train atteint enfin Porto-Vecchio, à cinq heures de Bastia."},{"at":286.86,"end":294.16,"text":"Il ne connaîtra que huit étés. En septembre 1943, les bombardements coupent la voie. Elle ne rouvrira jamais."}],"cues":{"train":281.28},"pins":{}},{"id":"fievre","from":295.36,"arrive":303.36,"voice":297.96,"leave":313.46,"lines":[{"at":298.06,"end":305.52,"text":"Voici l’anse au lendemain de la guerre, encore sauvage. Le mal qui vidait cette plaine depuis quatre siècles vient tout juste de céder."},{"at":306,"end":312.76,"text":"Entre les deux guerres déjà, le maire d’alors, le docteur Camille de Rocca Serra, avait appuyé la lutte contre le paludisme."}],"cues":{},"pins":{}},{"id":"rivage-1975","from":313.46,"arrive":319.46,"voice":314.86,"leave":332.18,"lines":[{"at":314.94,"end":320.22,"text":"Au printemps 1949, l’État lance sa campagne contre les moustiques par Porto-Vecchio."},{"at":320.43,"end":323.74,"text":"En deux ans, la fièvre s’effondre presque à zéro."},{"at":323.95,"end":331.18,"text":"En 1950, le fils de Camille, Jean-Paul, médecin lui aussi, devient maire. Il le restera quarante-sept ans."}],"cues":{},"pins":{"analyses":320.43}},{"id":"rivage-2024","from":332.18,"arrive":338.18,"voice":333.58,"leave":346.2,"lines":[{"at":333.68,"end":338.63,"text":"Les digues s’avancent, les quais s’ouvrent. Une même anse, méconnaissable."},{"at":339.03,"end":345.1,"text":"Pour la première fois, on n’a plus à fuir Porto-Vecchio quand vient la chaleur. On peut enfin y passer l’été."}],"cues":{},"pins":{}},{"id":"ete","from":346.2,"arrive":353.2,"voice":348.8,"leave":359.88,"lines":[{"at":348.88,"end":355.77,"text":"Alors les saisons se retournent. Pendant trois siècles, l’été vidait la ville ; désormais, il la remplit."},{"at":355.93,"end":358.48,"text":"En une vie d’homme, elle fait plus que tripler."}],"cues":{},"pins":{"habitants":355.93}},{"id":"plages","from":359.88,"arrive":365.88,"voice":361.28,"leave":381.9,"lines":[{"at":361.42,"end":364.73,"text":"Palombaggia, Santa Giulia, Cala Rossa."},{"at":364.91,"end":371.88,"text":"Là-haut, à l’Ospédale, le lac retient l’eau qui abreuve la côte — la montagne fait toujours vivre la plaine."},{"at":371.99,"end":376.09,"text":"Ceux qui arrivent chaque été refont sans le savoir un très vieux chemin."},{"at":376.23,"end":380.4,"text":"Vous, vous ne venez pas voir cette mer. Vous venez la retrouver."}],"cues":{},"pins":{}},{"id":"soir","from":381.9,"arrive":389.9,"voice":384.5,"leave":409.7,"lines":[{"at":384.58,"end":391.63,"text":"Le 31 juillet au soir, on promène dans la vieille ville Luddareddu, « petit juillet », un mannequin de paille et de liège."},{"at":391.86,"end":396.07,"text":"On le juge, on le pend, et à minuit on le brûle devant l’église."},{"at":396.59,"end":401.55,"text":"Juillet était le mois du liège et du sel, celui où les hommes restaient seuls en plaine."},{"at":401.76,"end":408.5,"text":"Le brûler, c’était fêter le droit de remonter. On le brûle toujours, dans une ville où l’on vient désormais passer l’été."}],"cues":{},"pins":{}},{"id":"deux-rues","from":409.7,"arrive":417.7,"voice":412.3,"leave":434.62,"lines":[{"at":412.38,"end":418.86,"text":"Approchez-vous encore. Le long des vieux murs génois, une ruelle porte le nom du docteur Camille de Rocca Serra."},{"at":419.07,"end":423.03,"text":"Au bout, sans même tourner, elle devient la rue du Général-Abbatucci."},{"at":423.21,"end":429.59,"text":"Ce n’est pas un hasard. Le docteur Camille est né à Zicavo, le village des Abbatucci — sa mère portait leur nom."},{"at":429.74,"end":433.02,"text":"Depuis longtemps déjà, la montagne et la mer s’étaient épousées."}],"cues":{},"pins":{}},{"id":"rue","from":434.62,"arrive":445.62,"voice":439.62,"leave":452.82,"lines":[{"at":439.7,"end":444.02,"text":"La voici, à hauteur de pas. Ici, les cartes s’arrêtent sur le seuil."},{"at":444.42,"end":448.95,"text":"Déjà, dans cette rue, des volets se sont rouverts. Car la maison n’oublie rien."},{"at":449.11,"end":451.22,"text":"A casa piglia, a casa rende.","sub":"La maison rend toujours ce qu’elle prend.","kind":"proverb"}],"cues":{},"pins":{}},{"id":"envoi","from":452.82,"arrive":462.82,"voice":458.32,"leave":481.28,"lines":[{"at":458.56,"end":463.2,"text":"La nuit tombe sur Portivechju. Des fenêtres s’allument au-dessus des salines."},{"at":463.42,"end":470.81,"text":"Ici, tout le monde est parti, et tout le monde a retrouvé le chemin — les bergers, les montagnards, Paoli lui-même."},{"at":470.97,"end":475.93,"text":"Si vous écoutez ceci de loin, vous n’êtes pas de passage. Vous êtes le prochain retour."},{"at":476.09,"end":479.28,"text":"Vous ne reconnaîtrez rien, et tout vous reconnaîtra."}],"cues":{},"pins":{}},{"id":"dedicace","from":481.28,"arrive":489.28,"voice":485.78,"leave":498.98,"lines":[{"at":485.94,"end":489.95,"text":"Aux Rocca Serra et aux Abbatucci, et à tous ceux qui en descendent.","quiet":true},{"at":490.64,"end":492.66,"text":"Ici commence toujours le retour.","quiet":true},{"at":493.44,"end":494.98,"text":"Pace è salute.","quiet":true}],"cues":{},"pins":{}}]};
